/**
 * THE SOURCED-DATA LOADER (plan 2026-10-17 replicable pages, Task 4): the only way a page builder reads data/sourced/. The files are
 * imported statically through ./files (generated by scripts/gen_sourced_index.ts; the sourced-data gate reds when it misses a file),
 * so nothing here touches the network or the file system at runtime.
 *  - sourcedRows(filter): every row matching item, trade, geo code and level, each with its source resolved (a row's own source
 *    overrides its file's) and its file's id.
 *  - sourcedOne(item, trade, geo, measure?): the row of the most recent year, or null. `trade: null` asks for a row with no trade;
 *    `measure` picks one class where an item has several (pay by job, size classes).
 *  - sourcesFor(rows): the distinct sources of rows, in first-seen order (the Sources section).
 * makeSourced builds the same three over any files (the tests use the fixtures under ./__fixtures__).
 * A row marked `unconfirmed` (data note 34: read through one route only) is never handed out: it stays in its file with its note.
 * A row keyed by `classCode` (data-trades' files: one official class serves many trades, the trade-to-class join is the class map) is
 * kept apart, read only through sourcedClassRows: a builder asking for a trade-less row of an item (`trade: null`) never meets the
 * hundreds of class rows that carry no `trade` either (S-U1, 2026-10-20).
 */
import type { Level, ResolvedRow, SourcedFile, Source } from "./schema";
import { SOURCED_FILES } from "./files";

export type { Level, ResolvedRow, Source, SourcedFile, SourcedRow } from "./schema";

export type RowFilter = { item?: string; trade?: string; geo?: string; level?: Level; measure?: string };
export type ClassFilter = { item?: string; classCode?: string; geo?: string; level?: Level };

/** Year strings start with four digits ("2024", "2023/24", "2026-03"): order by the year, then the whole string. */
export function yearOrder(a: string, b: string): number {
  const ya = Number(a.slice(0, 4)), yb = Number(b.slice(0, 4));
  return ya !== yb ? ya - yb : a.localeCompare(b);
}

export function makeSourced(files: readonly SourcedFile[]) {
  const resolved: ResolvedRow[] = files.flatMap((f) => f.rows.filter((r) => r.unconfirmed !== true).map((r) => ({ ...r, source: r.source ?? f.source, fileId: f.id })));
  const all = resolved.filter((r) => r.classCode === undefined);
  const classed = resolved.filter((r) => r.classCode !== undefined);

  function sourcedRows(filter: RowFilter = {}): ResolvedRow[] {
    return all.filter((r) =>
      (filter.item === undefined || r.item === filter.item) &&
      (filter.trade === undefined || r.trade === filter.trade) &&
      (filter.geo === undefined || r.geo.code === filter.geo) &&
      (filter.level === undefined || r.geo.level === filter.level) &&
      (filter.measure === undefined || r.measure === filter.measure));
  }

  function sourcedOne(item: string, trade: string | null, geo: string, measure?: string): ResolvedRow | null {
    const rows = all.filter((r) => r.item === item && (trade === null ? r.trade === undefined : r.trade === trade) &&
      r.geo.code === geo && (measure === undefined || r.measure === measure));
    if (!rows.length) return null;
    return rows.reduce((best, r) => (yearOrder(r.year, best.year) > 0 ? r : best));
  }

  /** The rows keyed by official class (data-trades' files), by item, class code, geo code and level. */
  function sourcedClassRows(filter: ClassFilter = {}): ResolvedRow[] {
    return classed.filter((r) =>
      (filter.item === undefined || r.item === filter.item) &&
      (filter.classCode === undefined || r.classCode === filter.classCode) &&
      (filter.geo === undefined || r.geo.code === filter.geo) &&
      (filter.level === undefined || r.geo.level === filter.level));
  }

  return { sourcedRows, sourcedOne, sourcedClassRows, sourcesFor };
}

/** The distinct sources of rows (by URL and title), in first-seen order. */
export function sourcesFor(rows: ReadonlyArray<{ source?: Source }>): Source[] {
  const seen = new Map<string, Source>();
  for (const r of rows) {
    if (!r.source) continue;
    const key = `${r.source.url}\n${r.source.title}`;
    if (!seen.has(key)) seen.set(key, r.source);
  }
  return [...seen.values()];
}

const site = makeSourced(SOURCED_FILES);
export const sourcedRows = site.sourcedRows;
export const sourcedOne = site.sourcedOne;
export const sourcedClassRows = site.sourcedClassRows;
export const SOURCED = SOURCED_FILES;
